/** 
 * Fetches the named attribute from the element. <p> Automatically appends  {@link #PREFIX} to the beginningof the name before looking up the attribute for format versions 3 and up.
 * @param version format version of the xml
 * @param element XML element to get the attribute from
 * @param name name of the attribute (without prefix)
 * @return named attribute
 */
public static String getAttribute(int version,Element element,String name){
  try {
    if (version >= 3) {
      return element.getAttribute(PREFIX + name);
    } else {
      return element.getAttribute(name);
    }
  } catch (NullPointerException e) {
    // Handle the exception, e.g., log it or return a default value
    return null; // or throw a custom exception, or log and return a default value
  }
}
